    private static final class IntegrityReport {
        private final List<IndexEntry> entries;
        private final List<Path> unownedFiles;
        private boolean changed;

        private IntegrityReport(List<IndexEntry> entries, List<Path> unownedFiles) {
            this.entries = entries;
            this.unownedFiles = unownedFiles;
        }

        private boolean hasProblems() {
            for (IndexEntry entry : entries) {
                if (entry.broken || entry.resolved || entry.shared || entry.misplaced || entry.colliding || entry.occupied) {
                    return true;
                }
            }
            return !unownedFiles.isEmpty();
        }

        private String message() {
            List<String> sections = new ArrayList<>();
            addEntries(sections, "broken", filter(entry -> entry.broken));
            addEntries(sections, "resolved", filter(entry -> entry.resolved));
            addEntries(sections, "shared", filter(entry -> entry.shared));
            if (!unownedFiles.isEmpty()) {
                List<String> names = new ArrayList<>();
                for (Path file : unownedFiles) {
                    names.add(file.getFileName().toString());
                }
                sections.add("unowned files [" + String.join(", ", names) + "]");
            }
            addEntries(sections, "misplaced", filter(entry -> entry.misplaced));
            addEntries(sections, "colliding", filter(entry -> entry.colliding));
            addEntries(sections, "occupied", filter(entry -> entry.occupied));
            return "Violation store integrity check failed: " + String.join("; ", sections);
        }

        private List<IndexEntry> filter(EntryPredicate predicate) {
            List<IndexEntry> result = new ArrayList<>();
            for (IndexEntry entry : entries) {
                if (predicate.test(entry)) {
                    result.add(entry);
                }
            }
            result.sort(Comparator.comparing(entry -> entry.description));
            return result;
        }

        private void addEntries(List<String> sections, String label, List<IndexEntry> entries) {
            if (entries.isEmpty()) {
                return;
            }
            List<String> descriptions = new ArrayList<>();
            for (IndexEntry entry : entries) {
                descriptions.add("'" + entry.description + "' -> '" + entry.fileName + "'");
            }
            sections.add(label + " entries [" + String.join(", ", descriptions) + "]");
        }
    }

    @FunctionalInterface
    private interface EntryPredicate {
        boolean test(IndexEntry entry);
    }

