     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
     */
    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
        if (ruleViolationFileNameStrategy == null) {
            throw new NullPointerException("ruleViolationFileNameStrategy");
        }
        this.constructorStrategy = ruleViolationFileNameStrategy;
        this.strategyConfiguredByConstructor = true;
    }

    @Override
    public void initialize(Properties properties) {
        initialized = false;
        configure(properties);
        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Repairing the violation store requires %s.%s=true",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }
        Path configuredFolder = Paths.get(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT)).toAbsolutePath().normalize();
        Object lock = lockFor(configuredFolder);

        synchronized (lock) {
            Path index = configuredFolder.resolve(STORED_RULES_FILE_NAME);
            storeFolder = configuredFolder;
            storedRulesFile = index;
            storeLock = lock;
            boolean indexExists = entryExists(index);
            if (!indexExists && !Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT))) {
                throw new StoreInitializationFailedException(String.format(
                        "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
            }
            try {
                Files.createDirectories(configuredFolder);
            } catch (IOException | SecurityException e) {
                throw new StoreInitializationFailedException(e);
            }
            if (!Files.isDirectory(configuredFolder)) {
                throw new StoreInitializationFailedException("Configured violation store path is not a directory: " + configuredFolder);
            }
            indexExists = entryExists(index);
            if (indexExists && !Files.isRegularFile(index, LinkOption.NOFOLLOW_LINKS)) {
                throw new StoreInitializationFailedException("The violation store index is not a regular file directly in the store folder: " + index);
            }

            Properties rules = indexExists ? loadProperties(index) : new Properties();
            log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), index.toAbsolutePath());

            IntegrityReport report = null;
            if (integrityMode != IntegrityMode.IGNORE) {
                report = inspect(rules, index, configuredFolder);
                if (integrityMode == IntegrityMode.FAIL && report.hasProblems()) {
                    throw new StoreInitializationFailedException(report.message());
                }
                if (integrityMode == IntegrityMode.REPAIR) {
                    repair(rules, report);
                    if (report.changed || !indexExists) {
                        writeProperties(index, rules);
                    }
                }
            }
            if (integrityMode != IntegrityMode.REPAIR && !indexExists) {
                writeProperties(index, rules);
            }

            storeFolder = configuredFolder;
            storedRulesFile = index;
            storeLock = lock;
            initialized = true;
        }
    }

    private void configure(Properties properties) {
        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
        String configuredIntegrity = properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_IGNORE);
        if (INTEGRITY_IGNORE.equals(configuredIntegrity)) {
            integrityMode = IntegrityMode.IGNORE;
        } else if (INTEGRITY_REPAIR.equals(configuredIntegrity)) {
            integrityMode = IntegrityMode.REPAIR;
        } else if (INTEGRITY_FAIL.equals(configuredIntegrity)) {
            integrityMode = IntegrityMode.FAIL;
        } else {
            throw new StoreInitializationFailedException(String.format(
                    "Invalid %s '%s'; accepted values are '%s', '%s' and '%s'",
                    INTEGRITY_PROPERTY_NAME, configuredIntegrity, INTEGRITY_REPAIR, INTEGRITY_FAIL, INTEGRITY_IGNORE));
        }

        String configuredFileNames = properties.getProperty(FILE_NAMES_PROPERTY_NAME);
        if (strategyConfiguredByConstructor) {
            if (configuredFileNames != null) {
                throw new StoreInitializationFailedException(String.format(
                        "Property %s cannot be configured when a RuleViolationFileNameStrategy was supplied to the constructor",
                        FILE_NAMES_PROPERTY_NAME));
            }
            activeStrategy = constructorStrategy;
            randomFileNames = false;
        } else if (configuredFileNames == null || FILE_NAMES_RANDOM.equals(configuredFileNames)) {
            activeStrategy = constructorStrategy;
            randomFileNames = true;
        } else if (FILE_NAMES_DESCRIPTION.equals(configuredFileNames)) {
            activeStrategy = new DescriptionFileNameStrategy();
            randomFileNames = false;
        } else {
            activeStrategy = instantiateStrategy(configuredFileNames);
            randomFileNames = false;
        }
    }

    private RuleViolationFileNameStrategy instantiateStrategy(String className) {
        try {
            Class<?> type = Class.forName(className);
            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(type)) {
                throw new IllegalArgumentException("does not implement " + RuleViolationFileNameStrategy.class.getName());
            }
    }

    @Override
    public boolean contains(ArchRule rule) {
        synchronized (lock()) {
            return findEntry(loadCurrentProperties(), rule.getDescription()) != null;
        }
    }

    @Override
    public void save(ArchRule rule, List<String> violations) {
        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
        if (!storeUpdateAllowed) {
            throw new StoreUpdateFailedException(String.format(
                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }
        synchronized (lock()) {
            Properties rules = loadCurrentProperties();
            IndexEntry existing = findEntry(rules, rule.getDescription());
            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR && existing != null) {
                forgetKnownRule(rules, existing);
                return;
            }

            String fileName;
            boolean newEntry = existing == null;
            if (newEntry) {
                if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
                    return;
                }
                fileName = createFileName(rule.getDescription());
                ensureNewEntryDoesNotConflict(rules, fileName);
            } else {
                fileName = existing.fileName;
            }

            SaveTarget target = validateSaveTarget(fileName, newEntry);
            byte[] contents = encodeViolations(violations);
            try {
                writeViolationFile(target.path, contents, target.exists);
                if (newEntry) {
                    rules.setProperty(rule.getDescription(), fileName);
                    try {
                        writeProperties(storedRulesFile, rules);
                    } catch (RuntimeException e) {
                        deleteEntryFile(target.path);
                        throw e;
                    }
                }
            } catch (IOException e) {
                throw new StoreUpdateFailedException(e);
            }
        }
    }

    private void forgetKnownRule(Properties rules, IndexEntry entry) {
        boolean shared = sharesFileOrName(rules, entry);
        if (!shared) {
            // Commit the index change first. If deleting the file is rejected, restore the index.
            rules.remove(entry.description);
            writeProperties(storedRulesFile, rules);
